<?php

declare(strict_types=1);

namespace App\Payment\Domain\Model;

enum PaymentProvider: string
{
    case STRIPE = 'STRIPE';
    case CASH = 'CASH';
    case CARD_TERMINAL = 'CARD_TERMINAL';
    /** Invitations: nothing to pay. */
    case NONE = 'NONE';
    /** Demo data generated by fixtures. */
    case FIXTURE = 'FIXTURE';

    public function label(): string
    {
        return match ($this) {
            self::STRIPE => 'Carte en ligne',
            self::CASH => 'Espèces',
            self::CARD_TERMINAL => 'Terminal de paiement',
            self::NONE => 'Invitation',
            self::FIXTURE => 'Démo',
        };
    }
}
